subroutine Normalize(a as integer by reference, b as integer by reference)
    define auxiliary as integer;
    if a > b then
        auxiliary <- a;
        a <- b;
        b <- auxiliary;
    endIf
endSubroutine

algorithm RunNormalization
    define x as integer;
    define y as integer;
    read x;
    read y;
    Normalize(x, y);
    write x;
    write y;
endAlgorithm

