subroutine Swap(a as integer by reference, b as integer by reference)
    define temp as integer;
    temp <- a;
    a <- b;
    b <- temp;
endSubroutine

algorithm RunNormalization
    define n1 as integer;
    define n2 as integer;
    read n1;
    read n2;
    Swap(n1, n2);
    write n1;
    write n2;
endAlgorithm
